package com.bank.repart.core;

import com.bank.repart.model.Txn;
import java.util.*;
import java.util.logging.Logger;

// Models repartition (wide, full shuffle, even) vs coalesce (narrow, no shuffle, uneven).
public class Partitioner {
    private static final Logger log = Logger.getLogger(Partitioner.class.getName());

    // repartition(n): WIDE — full shuffle, round-robin into n EVEN partitions.
    public List<List<Txn>> repartition(List<List<Txn>> partitions, int n) {
        log.info(() -> "repartition(" + n + "): WIDE transformation → FULL SHUFFLE (round-robin)");
        // Flatten all records (this represents moving everything across the network).
        List<Txn> all = new ArrayList<>();
        for (List<Txn> p : partitions) all.addAll(p);
        int shuffled = all.size();
        log.warning(() -> "repartition shuffled " + shuffled + " records across the network");

        // Deal round-robin into exactly n partitions → even sizes.
        List<List<Txn>> out = new ArrayList<>();
        for (int i = 0; i < n; i++) out.add(new ArrayList<>());
        for (int i = 0; i < all.size(); i++) out.get(i % n).add(all.get(i));
        log.info(() -> "repartition produced " + n + " EVEN partitions, sizes=" + sizes(out));
        return out;
    }

    // coalesce(n): NARROW — NO shuffle, stitch existing partitions, only DECREASE.
    public List<List<Txn>> coalesce(List<List<Txn>> partitions, int n) {
        if (n > partitions.size()) {
            log.warning(() -> "coalesce(" + n + "): cannot INCREASE without shuffle → "
                    + "returning original " + partitions.size() + " partitions unchanged");
            return partitions;
        }
        log.info(() -> "coalesce(" + n + "): NARROW transformation → NO shuffle (merge in place)");
        // Assign existing partitions to n groups without moving records across the network.
        List<List<Txn>> out = new ArrayList<>();
        for (int i = 0; i < n; i++) out.add(new ArrayList<>());
        for (int i = 0; i < partitions.size(); i++) {
            out.get(i % n).addAll(partitions.get(i)); // stitch whole partitions together
        }
        log.info(() -> "coalesce produced " + n + " partitions (possibly UNEVEN), sizes=" + sizes(out));
        return out;
    }

    private List<Integer> sizes(List<List<Txn>> parts) {
        List<Integer> s = new ArrayList<>();
        for (List<Txn> p : parts) s.add(p.size());
        return s;
    }
}
