package com.bank.repart;

import com.bank.repart.core.Partitioner;
import com.bank.repart.model.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class RepartitionDemo {
    private static final Logger log = Logger.getLogger(RepartitionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new RepartLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Skewed partitions: one big, others small (after an uneven filter).
        List<List<Txn>> skewed = new ArrayList<>();
        List<Txn> big = new ArrayList<>();
        for (int i = 0; i < 6; i++) big.add(new Txn("SAV2001", new BigDecimal("1000")));
        skewed.add(big);                                           // size 6
        skewed.add(List.of(new Txn("CUR3001", new BigDecimal("500")))); // size 1
        skewed.add(List.of(new Txn("SAV2001", new BigDecimal("300")))); // size 1

        Partitioner p = new Partitioner();

        // repartition(2): full shuffle → even sizes (shuffle cost).
        log.info("=== repartition(2): rebalance before a heavy join ===");
        p.repartition(skewed, 2);

        // coalesce(2): no shuffle → cheap but uneven.
        log.info("=== coalesce(2): cheap reduce before writing files ===");
        p.coalesce(skewed, 2);

        // coalesce to a LARGER number: no effect (cannot increase without shuffle).
        log.info("=== coalesce(5): attempt to increase ===");
        p.coalesce(skewed, 5);
    }
}

